from django.test import TestCase
from django.urls import reverse
from .models import Post

class PostViewTests(TestCase):
    @classmethod
    def setUpTestData(cls):
        cls.post = Post.objects.create(title="Hello", slug="hello", published=True)

    def test_list_shows_published_posts(self):
        response = self.client.get(reverse("blog:list"))
        self.assertEqual(response.status_code, 200)
        self.assertContains(response, "Hello")

    def test_anonymous_user_is_redirected_from_create(self):
        response = self.client.get(reverse("blog:create"))
        self.assertRedirects(response, f"{reverse('login')}?next={reverse('blog:create')}")

from django.core import mail
from django.test import TestCase, override_settings

@override_settings(EMAIL_BACKEND="django.core.mail.backends.locmem.EmailBackend")
class EmailTests(TestCase):
    def test_welcome_email_is_sent(self):
        self.client.post("/signup/", {"email": "ada@example.com"})
        self.assertEqual(len(mail.outbox), 1)
        self.assertIn("Welcome", mail.outbox[0].subject)

